<?php use SwimlogStandalone\CalendarView as CV; ?>
<section class="calendar-panel" aria-labelledby="calendar-title"<?php if(!is_wp_error($calendar)&&current_user_can('swimlog_manage_own_workouts')): ?> data-plan-calendar data-today="<?php echo esc_attr($calendar['today']->format('Y-m-d')); ?>" data-drag-nonce="<?php echo esc_attr(wp_create_nonce('swimlog_plan_drag')); ?>"<?php endif; ?>>
<?php if (is_wp_error($calendar)): ?>
<h2 id="calendar-title">Your calendar</h2><p role="alert"><?php echo esc_html($calendar->get_error_message()); ?></p>
<?php else: ?>
<div class="calendar-toolbar"><div><p class="eyebrow">YOUR CALENDAR</p><h2 id="calendar-title"><?php echo esc_html(($calendar['view']==='week' ? wp_date('M j',$calendar['start']->getTimestamp(),wp_timezone()).' – '.wp_date('M j, Y',$calendar['end']->getTimestamp(),wp_timezone()) : wp_date('F Y', $calendar['date']->getTimestamp(), wp_timezone()))); ?></h2></div>
<?php if(current_user_can('swimlog_manage_own_workouts')): ?><a class="control" href="<?php echo esc_url(CV::url($calendar['date'],$calendar['view']).'&edit_plan=new'); ?>">Plan workout</a><?php endif; ?>
<?php if(current_user_can('swimlog_manage_own_events')): ?><a class="control" data-add-event href="<?php echo esc_url(CV::url($calendar['date'],$calendar['view']).'&edit_event=new&event_date='.$calendar['date']->format('Y-m-d')); ?>">Add event</a><?php endif; ?>
<div class="calendar-controls"><a class="control" href="<?php echo esc_url(CV::url($calendar['previous'],$calendar['view'])); ?>" aria-label="Previous <?php echo esc_attr($calendar['view']); ?>">←</a><a class="control" href="<?php echo esc_url(CV::url($calendar['today'],$calendar['view'])); ?>">Today</a><a class="control" href="<?php echo esc_url(CV::url($calendar['next'],$calendar['view'])); ?>" aria-label="Next <?php echo esc_attr($calendar['view']); ?>">→</a></div>
<nav class="view-switch" aria-label="Calendar view"><?php foreach(array('month'=>'Month','week'=>'Week') as $view=>$label): ?><a class="control" <?php if($calendar['view']===$view) echo 'aria-current="true"'; ?> href="<?php echo esc_url(CV::url($calendar['date'],$view)); ?>"><?php echo esc_html($label); ?></a><?php endforeach; ?></nav>
<form method="get" class="date-jump"><label for="calendar-date">Go to date</label><input id="calendar-date" type="date" name="date" min="1900-01-01" max="2199-12-31" value="<?php echo esc_attr($calendar['date']->format('Y-m-d')); ?>"><input type="hidden" name="view" value="<?php echo esc_attr($calendar['view']); ?>"><button class="control">Go</button></form></div>
<p class="calendar-legend"><span class="legend-pool">Recorded</span><span class="legend-plan">Planned</span><span class="legend-event">Event</span><span>★ Personal best</span><span class="legend-matched">Matched swim</span></p>
<p class="plan-drag-status" data-plan-drag-status role="status" aria-live="polite" tabindex="-1"></p>
<div class="weekday-head" aria-hidden="true"><?php for($d=0;$d<7;$d++): ?><span><?php echo esc_html(wp_date('D',$calendar['start']->modify('+'.$d.' days')->getTimestamp(),wp_timezone())); ?></span><?php endfor; ?></div>
<?php if(isset($_GET['day'])): ?><p class="calendar-note"><a href="<?php echo esc_url(CV::url($calendar['date'],$calendar['view'])); ?>">Back to calendar</a></p><?php endif; ?>
<?php $chunks=array_chunk($calendar['days'],7,true); foreach($chunks as $index=>$days): ?>
<div class="calendar-week"><div class="calendar-grid">
<?php foreach($days as $key=>$day): $today=$key===$calendar['today']->format('Y-m-d'); $outside=$day['date']->format('m')!==$calendar['date']->format('m'); ?>
<section data-date="<?php echo esc_attr($key); ?>" class="calendar-day<?php echo $today?' is-today':''; echo $outside?' outside-month':''; ?>" aria-label="<?php echo esc_attr(wp_date('l, F j, Y',$day['date']->getTimestamp(),wp_timezone())); ?>"><h3><time datetime="<?php echo esc_attr($key); ?>"><span class="desktop-date"><?php echo esc_html($day['date']->format('j')); ?></span><span class="mobile-date"><?php echo esc_html(wp_date('D, M j',$day['date']->getTimestamp(),wp_timezone())); ?></span></time><?php if($today): ?><span class="today-label">Today</span><?php endif; ?></h3>
<?php if(current_user_can('swimlog_manage_own_workouts')&&$key>=$calendar['today']->format('Y-m-d')): ?><a class="plan-day-link" aria-label="<?php echo esc_attr('Plan workout for '.$key); ?>" href="<?php echo esc_url(CV::url($calendar['date'],$calendar['view']).'&edit_plan=new&planned_date='.$key); ?>">+ Plan workout</a><?php endif; ?>
<?php if(!$day['items']): ?><p class="empty-day">Nothing scheduled</p><?php endif; ?>
<div class="day-items"><?php require __DIR__.'/calendar-items.php'; ?></div>
<a class="control calendar-more" data-day-open aria-haspopup="dialog" href="<?php echo esc_url(CV::url($calendar['date'],$calendar['view']).'&day='.$key); ?>" aria-label="<?php echo esc_attr('Show all items for '.$key); ?>" hidden>…</a>
</section><?php endforeach; ?></div>
<?php $week=$calendar['weeks'][$index]??null; if($week): ?><p class="week-summary"><strong>Week of <?php echo esc_html(wp_date('M j',reset($days)['date']->getTimestamp(),wp_timezone())); ?></strong><span>Swimming: <?php echo esc_html(CV::distance($week['distance_m'])); ?> · <?php echo esc_html($week['workout_count']); ?> sessions</span><?php foreach(array('running'=>'Running','walking'=>'Walking') as $sport=>$label): if(!empty($week[$sport.'_count'])): ?><span><?php echo esc_html($label); ?>: <?php echo esc_html(!empty($week[$sport.'_distance_samples'])?CV::distance($week[$sport.'_distance_m']):'Distance unavailable'); ?></span><?php endif; endforeach; ?></p><?php endif; ?>
</div><?php endforeach; ?>
<p class="calendar-note"><?php if(current_user_can('swimlog_manage_own_workouts')): ?>On desktop, drag an unmatched, unlocked plan onto today or a future date to move it. Move and Copy are also available in plan details. <?php endif; ?>Select a session or plan to view details. Plan workouts for today or a future date; events can also be added or edited here.</p>
<dialog id="calendar-day-dialog" aria-labelledby="calendar-day-title"><div class="workout-dialog-header"><h2 id="calendar-day-title">Day view</h2><button type="button" data-day-close autofocus>Close day ×</button></div><div class="workout-dialog-body"><div data-day-actions></div><div data-day-items></div></div></dialog>
<script src="/assets/calendar-day.js" defer></script>
<?php endif; ?></section>
